//using Actuation, Movement2D, StandardSensors

// Boids Separation parameters
val separationRadius = 60.0

// Boids Separation Rule: steer away from neighbors that are too close.
// Force is proportional to how deeply the neighbor penetrated our comfort zone.
val repulsion = foldhood(Velocity.Zero)(_ + _) {
  val dist = nbrRange()
  if (dist < separationRadius && dist > 0.0) {
    // Vector pointing towards the neighbor
    val vectorToNeighbor = Cartesian(nbrVector().x, nbrVector().y)
    // Penetration depth into our personal space
    val penetration = separationRadius - dist
    // Steer in the opposite direction (-vectorToNeighbor)
    vectorToNeighbor.normalized * (-penetration)
  } else {
    Velocity.Zero
  }
}

// Gentle attraction to the center to keep the swarm together
val centerX = 300.0
val centerY = 300.0
val attractionSpeed = 15.0
val centerAttraction = goToPoint(centerX, centerY, attractionSpeed)
val finalVelocity = centerAttraction + repulsion

// Visual color effect: red when repelling, green when safe
val isRepelling = repulsion.module > 0.0
val color = mux(isRepelling) { ledAll to "red" } { ledAll to "green" }

// Actuate: return both velocity set and color as a pair
(velocity set finalVelocity, color)

//using Actuation, Movement2D, StandardSensors, BlockG, BlockS

// Constants
val leaderSpacing = 200
val closeRange = 120.0
val collisionRadius = 50.0
val repulsionForce = 80.0
val slowDownZone = 35.0
val proportionalGain = 1.4
val normalFollowerSpeed = 45.0
val leaderExploreSpeed = 15.0
val leaderExploreVision = 120.0
val leaderExploreTime = 30
val centerX = 300.0
val centerY = 300.0
val zoneWidth = 450.0
val zoneHeight = 450.0
val initialDistance = 0.0

// Elect leaders dynamically using Block S
val isLeader = S(leaderSpacing, () => nbrRange())

// Use Block G to compute the gradient (hop-distance) to the nearest leader node
val distToLeader = G(isLeader, initialDistance, (v: Double) => v + nbrRange(), () => nbrRange())

// Leaders are colored red, followers color-code by proximity (cyan if close, blue if far)
val isCloseToLeader = distToLeader < closeRange
val color = mux(isLeader) {
  ledAll to "red"
} {
  mux(isCloseToLeader) { ledAll to "cyan" } { ledAll to "blue" }
}

// Followers steer towards the neighbor pointing to the steepest gradient descent (min distToLeader)
val followLeaderVector = foldhood((distToLeader, Velocity.Zero)) { (acc, nbrVal) =>
  if (nbrVal._1 < acc._1) nbrVal else acc
} {
  (nbr{distToLeader}, Cartesian(nbrVector().x, nbrVector().y))
}._2

// Local repulsion force to prevent collision/overlap (separation)
val localRepulsion = foldhood(Velocity.Zero)(_ + _) {
  val d = nbrRange()
  val dir = Cartesian(nbrVector().x, nbrVector().y)
  if (d < collisionRadius && d > 0.0) {
    val force = (collisionRadius - d) / collisionRadius
    dir.normalized * (-repulsionForce * force * force)
  } else {
    Velocity.Zero
  }
}

// Combine forces for followers: attraction to leader + local separation
val followVelocity = if (distToLeader < slowDownZone) {
  followLeaderVector.normalized * (distToLeader * proportionalGain) + localRepulsion
} else {
  followLeaderVector.normalized * normalFollowerSpeed + localRepulsion
}

// Determine final velocity: Leaders move randomly, followers track leaders
val finalVelocity = mux(isLeader) {
  val explorationZone = RectangularZone(center = (centerX, centerY), width = zoneWidth, height = zoneHeight)
  explore(explorationZone, leaderExploreTime, leaderExploreVision, leaderExploreSpeed)
} {
  followVelocity
}

// Actuate: return both velocity set and color as a pair
(velocity set finalVelocity, color)

//using Actuation, Movement2D, StandardSensors

// Constants
val comfortZone = 65.0
val separationForce = 120.0
val cohesionWeight = 0.3
val separationWeight = 1.4
val alignmentWeight = 0.55
val inertiaFactor = 0.8
val steeringFactor = 0.2
val maxSpeed = 38.0
val minSpeed = 15.0
val speedColorThreshold = 25.0

// Flocking behavior (Boids rules: Cohesion, Separation, Alignment) with inertia
val flock = rep(Velocity.Zero) { prevVel =>
  val neighborCount = foldhood(0.0)(_ + _) { 1.0 }

  // 1. Cohesion: Move towards the center of mass of neighbors
  val cohesionSum = foldhood(Velocity.Zero)(_ + _) {
    Cartesian(nbrVector().x, nbrVector().y)
  }
  val cohesion = if (neighborCount > 1.0) cohesionSum / (neighborCount - 1.0) else Velocity.Zero

  // 2. Separation: Steer away from neighbors that are too close
  val separation = foldhood(Velocity.Zero)(_ + _) {
    val d = nbrRange()
    if (d < comfortZone && d > 0.0) {
      Cartesian(nbrVector().x, nbrVector().y).normalized * (-separationForce * (comfortZone - d) / comfortZone)
    } else {
      Velocity.Zero
    }
  }

  // 3. Alignment: Align with the average velocity of neighbors
  val alignmentSum = foldhood(Velocity.Zero)(_ + _) {
    nbr{prevVel}
  }
  val alignment = if (neighborCount > 1.0) alignmentSum / (neighborCount - 1.0) else Velocity.Zero

  // Combine boids forces with custom weights
  val steerForce = (cohesion * cohesionWeight) + (separation * separationWeight) + (alignment * alignmentWeight)

  // Blend previous velocity with steering force for smooth physical inertia/momentum
  val newVel = prevVel * inertiaFactor + steerForce * steeringFactor

  // Clamp speed limits to keep the flocking beautiful and constant
  val speed = newVel.module
  val clampedVel = if (speed > maxSpeed) {
    newVel.normalized * maxSpeed
  } else if (speed < minSpeed) {
    if (speed > 0.0) newVel.normalized * minSpeed else Cartesian(minSpeed, 0.0)
  } else {
    newVel
  }
  clampedVel
}

// Actuate: return both velocity set and color as a pair
(velocity set flock, mux(flock.module > speedColorThreshold) { ledAll to "cyan" } { ledAll to "magenta" })

