//using StandardSensors, BlockG, BlockC, BlockS, StateManagement

// Constants
val initialBaselineTemp = 20.0
val tempChangeStep = 0.1
val leaderSpacing = 200
val minComfortTemp = 12.0
val maxComfortTemp = 25.0
val activeNodeWeight = 1.0
val neutralValue = 0.0

trait Heater {
  def temp : Double
  def turnOn : Unit
  def turnOff : Unit
}
case class FakeHeater(baseline : Double) extends Heater {
  private var _temp = baseline
  private var on : Boolean = false
  override def temp: Double = {
    _temp += (if(on) { tempChangeStep } else { -tempChangeStep })
    _temp
  }
  def turnOn : Unit = on = true
  def turnOff : Unit = on = false
}
val heater = remember(FakeHeater(initialBaselineTemp))
val leader = S(leaderSpacing, () => nbrRange())
val potential = distanceTo(leader, () => nbrRange())
val count = C[Double, Double](potential, _ + _, activeNodeWeight, neutralValue)
val temperature = C[Double, Double](potential, _ + _, heater.temp, neutralValue)
val avg = temperature / count
val action : Heater => String = if(avg < minComfortTemp) {
  h => { h.turnOn; "turn on" }
} else if (avg > maxComfortTemp) {
  h => { h.turnOff; "turn off" }
} else {
  _ => "ok"
}
branch(leader) { "leader" } { action(heater) }

//using StandardSensors, Actuation, BlockG, BlockS

// Constants
val leaderSpacing = 500
val minDistance = 0.0
val maxDistance = 500.0
val maxColorIntensity = 255.0
val minColorIntensity = 16.0

def remap(min: Double, max: Double, newMin: Double, newMax: Double, x: Double): Double = {
  val nx = if(x < min) min else if(x > max) max else x
  (nx-min)/(max-min) * (newMax-newMin) + newMin
}
val leader = S(leaderSpacing, () => nbrRange())
val distance = distanceTo(leader)
val ledColor = mux(leader) { "red" } { s"#0000${remap(minDistance, maxDistance, maxColorIntensity, minColorIntensity, distance).toLong.toHexString}" }
ledAll to ledColor
